208	/// Trait for common types to send in POST, PUT or PATCH.
209	///
210	/// Sending common data types such as `String`, `&str` or `&[u8]` require no further wrapping
211	/// and can be sent either by [`RequestBuilder::send()`][crate::RequestBuilder::send] or using the
212	/// `http` crate [`Request`][http::Request] directly (see example below).
213	///
214	/// Implemented for:
215	///
216	/// * `&str`
217	/// * `&String`
218	/// * `&Vec<u8>`
219	/// * `&File`
220	/// * `&TcpStream`
221	/// * `&[u8]`
222	/// * `Response<Body>`
223	/// * `String`
224	/// * `Vec<u8>`
225	/// * `File`
226	/// * `Stdin`
227	/// * `TcpStream`
228	/// * `UnixStream` (not on windows)
229	/// * `&[u8; N]`
230	/// * `()`
231	///
232	/// # Example
233	///
234	/// These two examples are equivalent.
235	///
236	/// ```
237	/// let data: &[u8] = b"My special request body data";
238	///
239	/// let response = ureq::post("https://httpbin.org/post")
240	///     .send(data)?;
241	/// # Ok::<_, ureq::Error>(())
242	/// ```
243	///
244	/// Using `http` crate API
245	///
246	/// ```
247	/// use ureq::http;
248	///
249	/// let data: &[u8] = b"My special request body data";
250	///
251	/// let request = http::Request::post("https://httpbin.org/post")
252	///     .body(data)?;
253	///
254	/// let response = ureq::run(request)?;
255	/// # Ok::<_, ureq::Error>(())
256	/// ```
257	pub trait AsSendBody: Private {
258	    #[doc(hidden)]
259	    fn as_body(&mut self) -> SendBody;
260	}
261	
262	impl<'a> Private for SendBody<'a> {}
263	impl<'a> AsSendBody for SendBody<'a> {
264	    fn as_body(&mut self) -> SendBody {
265	        SendBody {
266	            inner: match &mut self.inner {
267	                BodyInner::None => BodyInner::None,
268	                BodyInner::ByteSlice(v) => BodyInner::ByteSlice(v),
269	                #[cfg(feature = "json")]
270	                BodyInner::ByteVec(v) => BodyInner::ByteSlice(v.get_ref()),
271	                BodyInner::Reader(v) => BodyInner::Reader(v),
272	                BodyInner::Body(v) => BodyInner::Reader(v),
273	                BodyInner::OwnedReader(v) => BodyInner::Reader(v),
274	            },
275	            size: self.size.take(),
276	            ended: self.ended,
277	            content_type: self.content_type.take(),
278	        }
279	    }
280	}
281	
282	pub(crate) enum BodyInner<'a> {
283	    None,
284	    ByteSlice(&'a [u8]),
285	    #[cfg(feature = "json")]
286	    ByteVec(io::Cursor<Vec<u8>>),
287	    Body(Box<BodyReader<'a>>),
288	    Reader(&'a mut dyn Read),
289	    OwnedReader(Box<dyn Read>),
290	}
291	
292	impl Private for &[u8] {}
293	impl AsSendBody for &[u8] {
294	    fn as_body(&mut self) -> SendBody {
295	        let inner = BodyInner::ByteSlice(self);
296	        (Some(self.len() as u64), inner).into()
297	    }
298	}
