135	#[allow(clippy::too_many_arguments)]
136	fn call_run(
137	    agent: &Agent,
138	    config: &Config,
139	    request_level: bool,
140	    mut call: Call<Prepare>,
141	    body: &mut SendBody,
142	    redirect_count: u32,
143	    redirect_history: &mut Option<Vec<Uri>>,
144	    timings: &mut CallTimings,
145	) -> Result<CallResult, Error> {
146	    let uri = call.uri().clone();
147	    debug!("{} {:?}", call.method(), DebugUri(call.uri()));
148	
149	    if config.https_only() && uri.scheme() != Some(&Scheme::HTTPS) {
150	        return Err(Error::RequireHttpsOnly(uri.to_string()));
151	    }
152	
153	    add_headers(&mut call, agent, config, body, &uri)?;
154	
155	    let mut connection = connect(agent, config, request_level, &uri, timings)?;
156	
157	    let mut call = call.proceed();
158	
159	    if log_enabled!(log::Level::Debug) {
160	        let headers = call.headers_map()?;
161	
162	        let r = DebugRequest {
163	            method: call.method(),
164	            uri: call.uri(),
165	            version: call.version(),
166	            headers,
167	        };
168	        debug!("{:?}", r);
169	    }
170	
171	    let call = match send_request(call, &mut connection, timings)? {
172	        SendRequestResult::Await100(call) => match await_100(call, &mut connection, timings)? {
173	            Await100Result::SendBody(call) => send_body(call, body, &mut connection, timings)?,
174	            Await100Result::RecvResponse(call) => call,
175	        },
176	        SendRequestResult::SendBody(call) => send_body(call, body, &mut connection, timings)?,
177	        SendRequestResult::RecvResponse(call) => call,
178	    };
179	
180	    let is_following_redirects = redirect_count < config.max_redirects();
181	
182	    let (mut response, response_result) = recv_response(
183	        call,
184	        &mut connection,
185	        config,
186	        timings,
187	        is_following_redirects,
188	    )?;
189	
190	    debug!("{:?}", DebugResponse(&response));
191	
192	    #[cfg(feature = "cookies")]
193	    {
194	        let mut jar = agent.cookie_jar_lock();
195	
196	        let iter = response
197	            .headers()
198	            .get_all(http::header::SET_COOKIE)
199	            .iter()
200	            .filter_map(|h| h.to_str().ok())
201	            .filter_map(|s| crate::Cookie::parse(s, &uri).ok());
202	
203	        jar.store_response_cookies(iter, &uri);
204	    }
205	
206	    if let Some(history) = redirect_history.as_mut() {
207	        history.push(uri.clone());
208	        response
209	            .extensions_mut()
210	            .insert(RedirectHistory(history.clone()));
211	    }
212	    response.extensions_mut().insert(ResponseUri(uri));
213	
214	    let ret = match response_result {
215	        RecvResponseResult::RecvBody(call) => {
216	            let timings = mem::take(timings);
217	            let mut handler = BodyHandler {
218	                call: Some(call),
219	                connection: Some(connection),
220	                timings,
221	                ..Default::default()
222	            };
223	
224	            if response.status().is_redirection() {
225	                if is_following_redirects {
226	                    let call = handler.consume_redirect_body()?;
227	
228	                    CallResult::Redirect(call, handler.timings)
229	                } else if config.max_redirects_do_error() {
230	                    return Err(Error::TooManyRedirects);
231	                } else {
232	                    CallResult::Response(response, handler)
233	                }
234	            } else {
235	                CallResult::Response(response, handler)
236	            }
237	        }
238	        RecvResponseResult::Redirect(call) => {
239	            cleanup(connection, call.must_close_connection(), timings.now());
240	
241	            if is_following_redirects {
242	                CallResult::Redirect(call, mem::take(timings))
243	            } else if config.max_redirects_do_error() {
244	                return Err(Error::TooManyRedirects);
245	            } else {
246	                CallResult::Response(response, BodyHandler::default())
247	            }
248	        }
249	        RecvResponseResult::Cleanup(call) => {
250	            cleanup(connection, call.must_close_connection(), timings.now());
251	            CallResult::Response(response, BodyHandler::default())
252	        }
253	    };
254	
255	    Ok(ret)
256	}
