268	fn add_headers(
269	    call: &mut Call<Prepare>,
270	    agent: &Agent,
271	    config: &Config,
272	    body: &mut SendBody,
273	    uri: &Uri,
274	) -> Result<(), Error> {
275	    let headers = call.headers();
276	
277	    let send_body_mode = if headers.has_send_body_mode() {
278	        None
279	    } else {
280	        Some(body.body_mode()?)
281	    };
282	    let has_header_accept_enc = headers.has_accept_encoding();
283	    let has_header_ua = headers.has_user_agent();
284	    let has_header_accept = headers.has_accept();
285	
286	    #[cfg(not(feature = "cookies"))]
287	    {
288	        let _ = agent;
289	        let _ = uri;
290	    }
291	    #[cfg(feature = "cookies")]
292	    {
293	        let value = agent.jar.get_request_cookies(uri);
294	        if !value.is_empty() {
295	            let value = HeaderValue::from_str(&value)
296	                .map_err(|_| Error::CookieValue("Cookie value is an invalid http-header"))?;
297	            call.header(header::COOKIE, value)?;
298	        }
299	    }
300	
301	    {
302	        static ACCEPTS: LazyLock<String> = LazyLock::new(|| {
303	            #[allow(unused_mut)]
304	            let mut value = String::with_capacity(10);
305	            #[cfg(feature = "gzip")]
306	            value.push_str("gzip");
307	            #[cfg(all(feature = "gzip", feature = "brotli"))]
308	            value.push_str(", ");
309	            #[cfg(feature = "brotli")]
310	            value.push_str("br");
311	            value
312	        });
313	
314	        let accepts = &*ACCEPTS;
315	
316	        if !has_header_accept_enc {
317	            if let Some(v) = config.accept_encoding().as_str(accepts) {
318	                // unwrap is ok because above ACCEPTS will produce a valid value,
319	                // or the value is user provided in which case it must be valid.
320	                let value = HeaderValue::from_str(v).unwrap();
321	                call.header(header::ACCEPT_ENCODING, value)?;
322	            }
323	        }
324	    }
325	
326	    if let Some(send_body_mode) = send_body_mode {
327	        match send_body_mode {
328	            BodyMode::LengthDelimited(v) => {
329	                let value = HeaderValue::from(v);
330	                call.header(header::CONTENT_LENGTH, value)?;
331	            }
332	            BodyMode::Chunked => {
333	                let value = HeaderValue::from_static("chunked");
334	                call.header(header::TRANSFER_ENCODING, value)?;
335	            }
336	            _ => {}
337	        }
338	    }
339	
340	    if !has_header_ua {
341	        // unwrap is ok because a user might override the agent, and if they
342	        // set bad values, it's not really ureq's problem.
343	        if let Some(v) = config.user_agent().as_str(DEFAULT_USER_AGENT) {
344	            let value = HeaderValue::from_str(v).unwrap();
345	            call.header(header::USER_AGENT, value)?;
346	        }
347	    }
348	
349	    if !has_header_accept {
350	        // unwrap is ok because a user might override accepts header, and if they
351	        // set bad values, it's not really ureq's problem.
352	        if let Some(v) = config.accept().as_str("*/*") {
353	            let value = HeaderValue::from_str(v).unwrap();
354	            call.header(header::ACCEPT, value)?;
355	        }
356	    }
357	
358	    Ok(())
359	}
360	
361	fn connect(
362	    agent: &Agent,
363	    config: &Config,
364	    request_level: bool,
365	    uri: &Uri,
366	    timings: &mut CallTimings,
367	) -> Result<Connection, Error> {
368	    // Before resolving the URI we need to ensure it is a full URI. We
369	    // cannot make requests with partial uri like "/path".
370	    uri.ensure_valid_url()?;
371	
372	    let is_proxy = config.proxy().is_some();
373	
374	    // For most proxy configs, the proxy itself should resolve the host name we are connecting to.
375	    // However for SOCKS4, we must do it and pass the resolved IP to the proxy.
376	    let is_proxy_local_resolve = config.proxy().map(|p| p.resolve_target()).unwrap_or(false);
377	
378	    // Tells if this host matches NO_PROXY
379	    let is_no_proxy = config.proxy().map(|p| p.is_no_proxy(uri)).unwrap_or(false);
380	
381	    let addrs = if is_no_proxy || !is_proxy || is_proxy_local_resolve {
382	        agent
383	            .resolver
384	            .resolve(uri, config, timings.next_timeout(Timeout::Resolve))?
385	    } else {
386	        agent.resolver.empty()
387	    };
388	
389	    timings.record_time(Timeout::Resolve);
390	
391	    let details = ConnectionDetails {
392	        uri,
393	        addrs,
394	        resolver: &*agent.resolver,
395	        config,
396	        request_level,
397	        now: timings.now(),
398	        timeout: timings.next_timeout(Timeout::Connect),
399	        current_time: timings.current_time(),
400	        run_connector: agent.run_connector.clone(),
401	    };
402	
403	    let use_pool = config.can_share_pool_with(&agent.config);
404	    let max_idle_age = config.max_idle_age().into();
405	    let connection = agent.pool.connect(&details, max_idle_age, use_pool)?;
406	
407	    if details.needs_tls() && !connection.is_tls() {
408	        return Err(Error::TlsRequired);
409	    }
410	
411	    timings.record_time(Timeout::Connect);
412	
413	    Ok(connection)
414	}
