416	fn send_request(
417	    mut call: Call<SendRequest>,
418	    connection: &mut Connection,
419	    timings: &mut CallTimings,
420	) -> Result<SendRequestResult, Error> {
421	    loop {
422	        if call.can_proceed() {
423	            break;
424	        }
425	
426	        let buffers = connection.buffers();
427	        let amount = call.write(buffers.output())?;
428	        let timeout = timings.next_timeout(Timeout::SendRequest);
429	        connection.transmit_output(amount, timeout)?;
430	    }
431	
432	    timings.record_time(Timeout::SendRequest);
433	
434	    // The request might be misconfigured.
435	    let call = call.proceed()?;
436	
437	    // We checked can_proceed() above, this unwrap is fine.
438	    Ok(call.unwrap())
439	}
