487	fn send_body(
488	    mut call: Call<SendBodyState>,
489	    body: &mut SendBody,
490	    connection: &mut Connection,
491	    timings: &mut CallTimings,
492	) -> Result<Call<RecvResponse>, Error> {
493	    loop {
494	        if call.can_proceed() {
495	            break;
496	        }
497	
498	        let buffers = connection.buffers();
499	
500	        let (tmp, output) = buffers.tmp_and_output();
501	
502	        let input_len = tmp.len();
503	
504	        let input_fitting_in_output = call.calculate_max_input(output.len());
505	        let max_input = input_len.min(input_fitting_in_output);
506	
507	        let output_used = if !call.is_chunked() {
508	            // For non-chunked, The body can be written directly to the output.
509	            // This optimizes away a memcopy if we were to go via call.write().
510	            let output_used = body.read(output)?;
511	
512	            // Size checking is still in the call.
513	            call.consume_direct_write(output_used)?;
514	
515	            output_used
516	        } else {
517	            let tmp = &mut tmp[..max_input];
518	            let n = body.read(tmp)?;
519	
520	            let (input_used, output_used) = call.write(&tmp[..n], output)?;
521	
522	            // Since output is "a bit" larger than the input (compensate for chunk ovexrhead),
523	            // the entire input we read from the body should also be shipped to the output.
524	            assert!(input_used == n);
525	
526	            output_used
527	        };
528	
529	        let timeout = timings.next_timeout(Timeout::SendBody);
530	        connection.transmit_output(output_used, timeout)?;
531	    }
532	
533	    timings.record_time(Timeout::SendBody);
534	    Ok(call.proceed().unwrap())
535	}
536	
537	fn recv_response(
538	    mut call: Call<RecvResponse>,
539	    connection: &mut Connection,
540	    config: &Config,
541	    timings: &mut CallTimings,
542	    is_following_redirects: bool,
543	) -> Result<(Response<()>, RecvResponseResult), Error> {
544	    let response = loop {
545	        let timeout = timings.next_timeout(Timeout::RecvResponse);
546	        let made_progress = connection.maybe_await_input(timeout)?;
547	
548	        let input = connection.buffers().input();
549	
550	        // If cookies are disabled, we can allow ourselves to follow
551	        // the redirect as soon as we discover the `Location` header.
552	        // There are plenty of broken servers out there that don't send
553	        // the finishing \r\n on redirects. With cookies off, we can
554	        // handle that situation.
555	        //
556	        // If cookies are enabled, we risk mising a `Set-Cookie` header
557	        // with such a strategy.
558	        let cookies_enabled = cfg!(feature = "cookies");
559	
560	        // If we are not following redirects, do not allow partial returned
561	        // 302 responses.
562	        let allow_partial_redirect = !cookies_enabled && is_following_redirects;
563	
564	        let (amount, maybe_response) = call.try_response(input, allow_partial_redirect)?;
565	
566	        let check_size = if maybe_response.is_some() {
567	            // We got a parsed response, ensure the size is within
568	            // configured parameters.
569	            amount
570	        } else {
571	            // We did not parse a response, if input is too large,
572	            // we stop trying to get more data.
573	            input.len()
574	        };
575	
576	        if check_size > config.max_response_header_size() {
577	            return Err(Error::LargeResponseHeader(
578	                input.len(),
579	                config.max_response_header_size(),
580	            ));
581	        }
582	
583	        connection.consume_input(amount);
584	
585	        if let Some(response) = maybe_response {
586	            assert!(call.can_proceed());
587	            break response;
588	        } else if !made_progress {
589	            return Err(Error::disconnected("recv_respone made no progress"));
590	        }
591	    };
592	
593	    timings.record_time(Timeout::RecvResponse);
594	    Ok((response, call.proceed().unwrap()))
595	}
596	
597	fn handle_redirect(mut call: Call<Redirect>, config: &Config) -> Result<Call<Prepare>, Error> {
598	    let maybe_new_call = call.as_new_call(config.redirect_auth_headers())?;
599	    let status = call.status();
600	
601	    if let Some(call) = maybe_new_call {
602	        debug!(
603	            "Redirect ({}): {} {:?}",
604	            status,
605	            call.method(),
606	            DebugUri(call.uri())
607	        );
608	
609	        Ok(call)
610	    } else {
611	        Err(Error::RedirectFailed)
612	    }
613	}
614	
615	fn cleanup(connection: Connection, must_close: bool, now: Instant) {
616	    if must_close {
617	        connection.close();
618	    } else {
619	        connection.reuse(now)
620	    }
621	}
622	
623	#[derive(Default)]
624	pub(crate) struct BodyHandler {
625	    call: Option<Call<RecvBody>>,
626	    connection: Option<Connection>,
627	    timings: CallTimings,
628	    remote_closed: bool,
629	    redirect: Option<Box<Call<Redirect>>>,
630	}
631	
632	impl BodyHandler {
633	    fn do_read(&mut self, buf: &mut [u8]) -> Result<usize, Error> {
634	        let (Some(call), Some(connection), timings) =
635	            (&mut self.call, &mut self.connection, &mut self.timings)
636	        else {
637	            return Ok(0);
638	        };
639	
640	        loop {
641	            let body_fulfilled = match call.body_mode() {
642	                BodyMode::NoBody => unreachable!("must be a BodyMode for BodyHandler"),
643	                // These modes are fulfilled by either reaching the content-length or
644	                // receiving an end chunk delimiter.
645	                BodyMode::LengthDelimited(_) | BodyMode::Chunked => call.can_proceed(),
646	                // This mode can only end once remote closes
647	                BodyMode::CloseDelimited => false,
648	            };
649	
650	            if body_fulfilled {
651	                self.ended()?;
652	                return Ok(0);
653	            }
654	
655	            let has_buffered_input = connection.buffers().can_use_input();
656	
657	            // First try to use input already buffered
658	            if has_buffered_input {
659	                let input = connection.buffers().input();
660	                let (input_used, output_used) = call.read(input, buf)?;
661	                connection.consume_input(input_used);
662	
663	                if output_used > 0 {
664	                    return Ok(output_used);
665	                }
666	
667	                if input_used > 0 {
668	                    // Body might be fulfilled now.
669	                    continue;
670	                }
671	            }
672	
673	            if self.remote_closed {
674	                // we should not try to await_input again.
675	                self.ended()?;
676	                return Ok(0);
677	            }
678	
679	            let timeout = timings.next_timeout(Timeout::RecvBody);
680	
681	            let made_progress = match connection.maybe_await_input(timeout) {
682	                Ok(v) => v,
683	                Err(Error::Io(e)) => match e.kind() {
684	                    io::ErrorKind::UnexpectedEof
685	                    | io::ErrorKind::ConnectionAborted
686	                    | io::ErrorKind::ConnectionReset => {
687	                        self.remote_closed = true;
688	                        true
689	                    }
690	                    _ => return Err(Error::Io(e)),
691	                },
692	                Err(e) => return Err(e),
693	            };
694	
695	            let input = connection.buffers().input();
696	            let input_ended = input.is_empty();
697	
698	            let (input_used, output_used) = call.read(input, buf)?;
699	            connection.consume_input(input_used);
700	
701	            if output_used > 0 {
702	                return Ok(output_used);
703	            } else if input_ended {
704	                self.ended()?;
705	                return Ok(0);
706	            } else if made_progress {
707	                // The maybe_await_input() made progress, but handled amount is 0. This
708	                // can for instance happen if we read some data, but not enough for
709	                // decoding any gzip.
710	                continue;
711	            } else {
712	                // This is an error case we don't want to see.
713	                return Err(Error::BodyStalled);
714	            }
715	        }
716	    }
717	
718	    fn ended(&mut self) -> Result<(), Error> {
719	        self.timings.record_time(Timeout::RecvBody);
720	
721	        let call = self.call.take().expect("ended() called with body");
722	
723	        // In some cases, when reading chunked, the server send 0\r\n to indicate
724	        // the end of the body, and then abruptly does a FIN. In these cases we have
725	        // received the entire body, but must clean up the connection.
726	        let is_ended_chunked = call.is_ended_chunked();
727	
728	        let mut force_close = false;
729	
730	        if !call.can_proceed() {
731	            if is_ended_chunked {
732	                // This case means we got 0\r\n, but can_proceed() is false because
733	                // it only goes true on fully received chunked bodies.
734	                debug!("Server ended connection after sending chunked 0\\r\\n");
735	                force_close = true;
736	            } else {
737	                return Err(Error::disconnected("ended call cannot proceed"));
738	            }
739	        }
740	
741	        let must_close_connection = force_close
742	            || match call.proceed().unwrap() {
743	                RecvBodyResult::Redirect(call) => {
744	                    let c = call.must_close_connection();
745	                    self.redirect = Some(Box::new(call));
746	                    c
747	                }
748	                RecvBodyResult::Cleanup(v) => v.must_close_connection(),
749	            };
750	
751	        let connection = self.connection.take().expect("ended() called with body");
752	        cleanup(connection, must_close_connection, self.timings.now());
753	
754	        Ok(())
755	    }
756	
757	    fn consume_redirect_body(&mut self) -> Result<Call<Redirect>, Error> {
758	        let mut buf = vec![0; 1024];
759	        loop {
760	            let amount = self.do_read(&mut buf)?;
761	            if amount == 0 {
762	                break;
763	            }
764	        }
765	
766	        // Unwrap is OK, because we are only consuming the redirect body if
767	        // such a body was signalled by the remote.
768	        let redirect = self.redirect.take().map(|b| *b);
769	        Ok(redirect.expect("remote to have signaled redirect"))
770	    }
771	}
772	
773	impl io::Read for BodyHandler {
774	    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
775	        self.do_read(buf).map_err(|e| e.into_io())
776	    }
777	}
