```rust
fn read_request(stream: &TcpStream) -> io::Result<Recorded> {
    let mut reader = BufReader::new(stream);
    // request line
    let mut line = String::new();
    reader.read_line(&mut line)?;
    let mut parts = line.trim().split(' ');
    let method = parts.next().unwrap().to_string();
    let target = parts.next().unwrap().to_string();
    // headers
    let mut headers = vec![];
    loop {
        let mut l = String::new();
        reader.read_line(&mut l)?;
        let t = l.trim();
        if t.is_empty() { break; }
        let (k, v) = t.split_once(':').unwrap();
        headers.push((k.trim().to_string(), v.trim().to_string()));
    }
    // body
    let body = read_body(&mut reader, &headers)?;
    Ok(Recorded { method, target, headers, body })
}

fn read_body(reader: &mut BufReader<&TcpStream>, headers: &[(String,String)]) -> io::Result<Vec<u8>> {
    let find = |name: &str| headers.iter().find(|(k,_)| k.eq_ignore_ascii_case(name)).map(|(_,v)| v.clone());
    if let Some(te) = find("transfer-encoding") {
        if te.to_ascii_lowercase().contains("chunked") {
            let mut body = vec![];
            loop {
                let mut size_line = String::new();
                reader.read_line(&mut size_line)?;
                let size_str = size_line.trim();
                let size = usize::from_str_radix(size_str.split(';').next().unwrap(), 16).map_err(...)?;
                if size == 0 {
                    // read trailers until empty line
                    loop {
                        let mut l = String::new();
                        reader.read_line(&mut l)?;
                        if l.trim().is_empty() { break; }
                    }
                    break;
                }
                let mut chunk = vec![0u8; size];
                reader.read_exact(&mut chunk)?;
                body.extend_from_slice(&chunk);
                let mut crlf = [0u8; 2];
                reader.read_exact(&mut crlf)?;
            }
            return Ok(body);
        }
    }
    if let Some(cl) = find("content-length") {
        let n: usize = cl.parse().unwrap();
        let mut body = vec![0u8; n];
        reader.read_exact(&mut body)?;
        return Ok(body);
    }
    Ok(vec![])
}
```

