+    // "" => [""]
+    // "/" => ["", ""]
+    // "/foo" => ["", "foo"]
+    // "/foo/" => ["", "foo", ""]
+    if joiner.len() > 1 {
+        joiner.pop();
+    }
+
+    for segment in location.split('/') {
+        if segment == "." {
