+        } else if segment == ".." {
+            if joiner.len() == 1 {
+                trace!("Location is relative above root");
+                return Err(ureq_proto::Error::BadLocationHeader(location.to_string()));
+            }
+            joiner.pop();
+        } else {
+            joiner.push(segment);
+        }
+    }
